import { BaseMessageChannel, MessageChannelFactory } from '../message-channels';
import { GetMessageEvent, IAuthenticatePayload, IGameChildEvents, IGameParentEvents, IKeyboardStatePayload, IOpenSubGamePayload, IOpenSubGameUrlPayload, IOperatorParentEvents, ISessionInfoPayload } from '../types';

export class SubGameProxy implements IGameChildEvents {
    public messageChannel: BaseMessageChannel<IGameChildEvents, IGameParentEvents>;
    private onMessageCallback: (event: GetMessageEvent<IOperatorParentEvents, keyof IOperatorParentEvents>) => void;
    private authPayload: IAuthenticatePayload | null = null;
    private reauthListener: ((event: MessageEvent) => void) | null = null;

    constructor(iframe: HTMLIFrameElement, onMessageCallback: (event: GetMessageEvent<IOperatorParentEvents, keyof IOperatorParentEvents>) => void) {
        this.messageChannel = MessageChannelFactory.create({ type: 'web', target: iframe, source: 'operator' });
        this.onMessageCallback = onMessageCallback;
        window.addEventListener('message', this.onMessageCallback);
    }

    public setKeyboardState(_payload: IKeyboardStatePayload): void {
        //no implementation
    }

    public async authenticate(payload: IAuthenticatePayload) {
        this.authPayload = payload;
        await this.messageChannel.waitForResponse('onInit', 'game');
        const authResponse = await this.sendAuthentication();
        this.listenForReauth();

        return authResponse;
    }

    // Reusable handshake performed once the sub-game has emits `onInit`
    private async sendAuthentication() {
        if (!this.authPayload) {
            return;
        }

        const authResponse = await this.messageChannel.makeRequest('authenticate', this.authPayload, 'onAuthenticated', 'game');
        await this.messageChannel.waitForResponse('onLoaded', 'game');

        return authResponse;
    }

    // When a sub-game reconnects it re-emits `onInit` and waits for the parent to re-send its credentials.
    private listenForReauth() {
        if (this.reauthListener) {
            return;
        }

        this.reauthListener = (event: MessageEvent) => {
            if (event.data?.type === 'onInit' && event.data?.source === 'game' && this.authPayload) {
                this.sendAuthentication();
            }
        };

        window.addEventListener('message', this.reauthListener);
    }

    public onSessionInfo(payload: ISessionInfoPayload): void {
        this.messageChannel.send('onSessionInfo', payload);
    }

    public async getSessionInfo() {
        return this.messageChannel.makeRequest('getSessionInfo', void 0, 'onSessionInfo', 'game');
    }

    public openSubGame(payload: IOpenSubGamePayload): void {
        this.messageChannel.send('openSubGame', payload);
    }

    public openSubGameUrl(payload: IOpenSubGameUrlPayload): void {
        this.messageChannel.send('openSubGameUrl', payload);
    }
    
    public requestAction(payload: { action: 'openSettings' | 'closeSettings'; }): void {
        return this.messageChannel.send('requestAction', payload);
    }

    public disconnect() {
        window.removeEventListener('message', this.onMessageCallback);

        if (this.reauthListener) {
            window.removeEventListener('message', this.reauthListener);
            this.reauthListener = null;
        }

        this.authPayload = null;
        this.messageChannel.send('disconnect', void 0);
    }
}